// Generates src/generated/capabilities.ts from catalog/capabilities.json.
//
// The catalog is the single source of truth for product identity, the
// current technical ID, bare tool names, gateway endpoints, token scopes,
// and the safe write-transaction state machine. It stores only bare tool
// names and capability metadata; fully-qualified MCP names are computed
// from the current technical ID (the SiYuan kernel derives the namespace
// from plugin.json name, so no second namespace is claimed).
//
// `renderCatalogModule` is shared by:
// - this script (writes the generated file),
// - scripts/check-capabilities.mjs (freshness gate in `pnpm build`),
// - tests/catalog.test.ts (freshness + consistency assertions).

import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(scriptDir, "..");
export const catalogPath = path.join(rootDir, "catalog", "capabilities.json");
export const outPath = path.join(rootDir, "src", "generated", "capabilities.ts");

/** Renders the TypeScript module for a parsed catalog object. */
export function renderCatalogModule(catalog) {
  const toolNames = catalog.pluginTools.map((tool) => tool.name);
  const readOnlyTools = catalog.pluginTools
    .filter((tool) => tool.readOnly)
    .map((tool) => tool.name);
  const confirmDefaultTools = catalog.pluginTools
    .filter((tool) => tool.confirmDefault)
    .map((tool) => tool.name);
  const toolCategories = Object.fromEntries(
    catalog.pluginTools.map((tool) => [tool.name, tool.category]),
  );

  const namespaces = catalog.namespaces;
  const pluginToolNames = toolNames.map((name) => `${namespaces.plugin}${name}`);

  const lines = [];
  lines.push("// AUTO-GENERATED by scripts/generate-capabilities.mjs — do not edit by hand.");
  lines.push("// Source of truth: catalog/capabilities.json");
  lines.push("// Regenerate with: pnpm run generate");
  lines.push("// Freshness is enforced by scripts/check-capabilities.mjs and tests/catalog.test.ts.");
  lines.push("");
  lines.push("export const CATALOG_SCHEMA_VERSION = 1;");
  lines.push(`export const PRODUCT_ID = ${JSON.stringify(catalog.product.id)};`);
  lines.push(`export const TECHNICAL_ID = ${JSON.stringify(catalog.product.technicalId)};`);
  lines.push(`export const PRODUCT_VERSION = ${JSON.stringify(catalog.product.version)};`);
  lines.push(`export const PRODUCT_DISPLAY_NAME_DEFAULT = ${JSON.stringify(catalog.product.displayName.default)};`);
  lines.push(`export const PRODUCT_DISPLAY_NAME_ZH_CN = ${JSON.stringify(catalog.product.displayName["zh-CN"])};`);
  lines.push(`export const MIN_APP_VERSION = ${JSON.stringify(catalog.product.minAppVersion)};`);
  lines.push("");
  lines.push("// The MCP namespace is derived from the current technical ID by the SiYuan");
  lines.push("// kernel. A single plugin cannot register a second native namespace.");
  lines.push("export const PLUGIN_NAMESPACE = " + JSON.stringify(namespaces.plugin) + ";");
  lines.push("export const GATEWAY_NAMESPACE = " + JSON.stringify(namespaces.gateway) + ";");
  lines.push("");
  lines.push("export const TOOL_NAMES = " + JSON.stringify(toolNames) + " as const;");
  lines.push("export const READ_ONLY_TOOLS = " + JSON.stringify(readOnlyTools) + " as const;");
  lines.push("export const CONFIRM_DEFAULT_TOOLS = " + JSON.stringify(confirmDefaultTools) + " as const;");
  lines.push("export const TOOL_CATEGORIES: Record<string, string> = " + JSON.stringify(toolCategories) + ";");
  lines.push("// Fully-qualified names under the current technical ID namespace.");
  lines.push("export const PLUGIN_TOOL_NAMES = " + JSON.stringify(pluginToolNames) + " as const;");
  lines.push("export const ORIGINAL_TOOL_COUNT = " + JSON.stringify(catalog.compatibility.originalToolCount) + ";");
  lines.push("");
  lines.push("export const GATEWAY_ENDPOINTS = " + JSON.stringify(catalog.gateway.endpoints) + " as const;");
  lines.push("export const TOKEN_SCOPES = " + JSON.stringify(catalog.gateway.token.scopes) + " as const;");
  lines.push("export const TOKEN_FORMAT = " + JSON.stringify(catalog.gateway.token.format) + ";");
  lines.push("export const TOKEN_ALGORITHM = " + JSON.stringify(catalog.gateway.token.algorithm) + ";");
  lines.push("export const TOKEN_DEFAULT_TTL_SECONDS = " + JSON.stringify(catalog.gateway.token.defaultTtlSeconds) + ";");
  lines.push("");
  lines.push("export const TXN_STATES = " + JSON.stringify(catalog.writeTransaction.states) + " as const;");
  lines.push("export const TXN_EVENTS = " + JSON.stringify(catalog.writeTransaction.events) + " as const;");
  lines.push("export const TXN_TERMINAL_STATES = " + JSON.stringify(catalog.writeTransaction.terminalStates) + " as const;");
  lines.push("export const TXN_NAME = " + JSON.stringify(catalog.writeTransaction.name) + ";");
  lines.push("export const TXN_MAX_PREVIEW_AGE_SECONDS = " + JSON.stringify(catalog.writeTransaction.maxPreviewAgeSeconds) + ";");
  lines.push("export const TXN_INVARIANTS = " + JSON.stringify(catalog.writeTransaction.invariants) + " as const;");
  lines.push("");
  lines.push("export interface CatalogTool {");
  lines.push("  name: string;");
  lines.push("  category: string;");
  lines.push("  readOnly: boolean;");
  lines.push("  confirmDefault: boolean;");
  lines.push("}");
  lines.push("");
  lines.push("export const CATALOG_TOOLS: CatalogTool[] = " + JSON.stringify(catalog.pluginTools) + ";");
  lines.push("");
  return lines.join("\n");
}

async function main() {
  const catalog = JSON.parse(await readFile(catalogPath, "utf8"));
  await writeFile(outPath, renderCatalogModule(catalog), "utf8");
  console.log(`Generated ${path.relative(rootDir, outPath)}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await main();
}
